 artifacts=render_previews(svg,d['icon_id'],48,r);shutil.copyfile(Path(d['fix_dir'])/'reference.png',r/'reference.png')
 d['omissions']=omissions.get(d['n'],'Secondary contour detail simplified for 48px clarity.')
